    const payload: Record<string, unknown> = { ["amount"]: Number((params.amount ?? '')), ["currency"]: String((params.currency ?? '')).toUpperCase(), ["order_id"]: (params.trx_id ?? ''), ["callback_url"]: (params.redirect_url ?? '') };
